package dev.cim.bridge;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

/**
 * M3.2 cross-version state translation (1.21.1 layer <-> 26.3 kernel).
 *
 * <p>Tables are GENERATED by {@code scripts/gen-remap-tables.py} from pinned
 * mcmeta snapshots (see remap-manifest.tsv) and ride the bootstrap jar as
 * {@code /cim/*.tsv} — the Rust mirror in {@code cim-registry} embeds the
 * same bytes, so both sides share one source of truth.
 *
 * <p>Measured drift 1.21.1 -> 26.3 (release, pinned):
 * <ul>
 *   <li>blocks 1060->1286: 1 rename (chain -> iron_chain), 227 additions,
 *       one value-set drift (note_block instrument gains trumpet*);</li>
 *   <li>entity_type: boat/chest_boat split per wood (default oak), thrown
 *       potion entity became splash_potion/lingering_potion;</li>
 *   <li>attributes flattened: generic.X / player.X -> X;</li>
 *   <li>no fluid registry change (5 -> 5).</li>
 * </ul>
 *
 * <p>Policy: translation is a pure string function; unknown states pass
 * through untouched; modded namespaces never enter the tables.
 */
public final class StateMapper {

    private static final String MINECRAFT = "minecraft:";
    private static volatile StateMapper instance;

    /** Lazy shared instance; tables are tiny (2 + 53 rows) so init is cheap. */
    public static StateMapper get() {
        StateMapper local = instance;
        if (local == null) {
            synchronized (StateMapper.class) {
                if (instance == null) {
                    instance = new StateMapper();
                }
                local = instance;
            }
        }
        return local;
    }

    /** Drift of one block's property set between the two versions. */
    private static final class PropDrift {
        final String kind; // "removed" | "added" | "changed"
        final String oldDefault;
        final String newDefault;
        final Map<String, String> map; // old value -> new value ("" = none)

        PropDrift(String kind, String oldDefault, String newDefault, Map<String, String> map) {
            this.kind = kind;
            this.oldDefault = oldDefault;
            this.newDefault = newDefault;
            this.map = map;
        }
    }

    private static final class BlockDrift {
        String renamedTo; // bare 26.3 key, null when the key survived
        final Map<String, PropDrift> props = new HashMap<>();
    }

    private final Map<String, BlockDrift> blocks;                 // bare old key
    private final Map<String, String> blockRenameInverse;         // bare new key -> old
    private final Map<String, Map<String, String>> registryPairs;         // registry -> old -> new
    private final Map<String, Map<String, String>> registryPairsInverse;  // registry -> new -> old
    final int removedKeyCount;

    private StateMapper() {
        this.blocks = new HashMap<>();
        this.blockRenameInverse = new HashMap<>();
        this.registryPairs = new HashMap<>();
        this.registryPairsInverse = new HashMap<>();
        int removed = 0;
        try (InputStream in = open("/cim/blockstate-drift.tsv")) {
            parseBlockstateDrift(in);
        } catch (IOException e) {
            throw new IllegalStateException("blockstate-drift.tsv unreadable", e);
        }
        try (InputStream in = open("/cim/registry-drift.tsv")) {
            removed = parseRegistryDrift(in);
        } catch (IOException e) {
            throw new IllegalStateException("registry-drift.tsv unreadable", e);
        }
        this.removedKeyCount = removed;
    }

    private static InputStream open(String resource) {
        InputStream in = StateMapper.class.getResourceAsStream(resource);
        if (in == null) {
            throw new IllegalStateException("missing resource " + resource
                    + " (regenerate via scripts/gen-remap-tables.py)");
        }
        return in;
    }

    // ---- table parsing -------------------------------------------------------

    private void parseBlockstateDrift(InputStream in) throws IOException {
        try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            String line;
            while ((line = r.readLine()) != null) {
                if (line.isEmpty() || line.charAt(0) == '#') {
                    continue;
                }
                int tab = line.indexOf('\t');
                if (tab <= 0) {
                    continue;
                }
                String key = line.substring(0, tab);
                String json = line.substring(tab + 1);
                BlockDrift drift = blocks.computeIfAbsent(bare(key), k -> new BlockDrift());
                int at = json.indexOf("\"renamedTo\":\"");
                if (at >= 0) {
                    int from = at + "\"renamedTo\":\"".length();
                    int to = json.indexOf('"', from);
                    drift.renamedTo = json.substring(from, to);
                    blockRenameInverse.put(drift.renamedTo, bare(key));
                }
                extractProps(json, "\"removed\":[", drift, "removed");
                extractProps(json, "\"added\":[", drift, "added");
                extractProps(json, "\"changed\":[", drift, "changed");
            }
        }
    }

    /**
     * The drift rows are single-line minified JSON; a full JSON parser is
     * overkill on the bootstrap loader, so the two known shapes are scanned
     * structurally: every brace-balanced object in the named array
     * contributes a PropDrift (nested "map" objects are brace-tracked).
     */
    private static void extractProps(String json, String marker, BlockDrift drift, String kind) {
        int start = json.indexOf(marker);
        if (start < 0) {
            return;
        }
        start += marker.length();
        int braceDepth = 0;
        int objStart = -1;
        for (int i = start; i < json.length(); i++) {
            char c = json.charAt(i);
            if (braceDepth > 0) {
                if (c == '{') {
                    braceDepth++;
                } else if (c == '}') {
                    braceDepth--;
                    if (braceDepth == 0) {
                        registerProp(drift, kind, json.substring(objStart, i));
                        objStart = -1;
                    }
                }
            } else if (c == '{') {
                braceDepth = 1;
                objStart = i + 1;
            } else if (c == ']') {
                return; // array ended
            }
        }
    }

    private static void registerProp(BlockDrift drift, String kind, String obj) {
        String name = strField(obj, "name");
        if (name == null) {
            return;
        }
        Map<String, String> map = new HashMap<>();
        if ("changed".equals(kind)) {
            map = mapField(obj, "map");
        }
        drift.props.put(name, new PropDrift(kind, strField(obj, "oldDefault"),
                strField(obj, "newDefault"), map));
    }

    private static String strField(String obj, String field) {
        int at = obj.indexOf("\"" + field + "\":\"");
        if (at < 0) {
            return null;
        }
        int from = at + field.length() + 4;
        int to = obj.indexOf('"', from);
        return to < 0 ? null : obj.substring(from, to);
    }

    /** Parse a flat {"a":"b",...} string-map field (values never escaped: ids are [a-z0-9_]). */
    private static Map<String, String> mapField(String obj, String field) {
        Map<String, String> out = new HashMap<>();
        int at = obj.indexOf("\"" + field + "\":{");
        if (at < 0) {
            return out;
        }
        int from = at + field.length() + 4;
        int end = obj.indexOf('}', from);
        if (end < 0) {
            return out;
        }
        for (String pair : obj.substring(from, end).split(",")) {
            int c = pair.indexOf(':');
            if (c <= 0) {
                continue;
            }
            String k = strip(pair.substring(0, c));
            String v = strip(pair.substring(c + 1));
            if (!k.isEmpty()) {
                out.put(k, v);
            }
        }
        return out;
    }

    private static String strip(String quoted) {
        String s = quoted.trim();
        if (s.length() >= 2 && s.charAt(0) == '"' && s.charAt(s.length() - 1) == '"') {
            s = s.substring(1, s.length() - 1);
        }
        return s;
    }

    private int parseRegistryDrift(InputStream in) throws IOException {
        int removed = 0;
        try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            String line;
            while ((line = r.readLine()) != null) {
                if (line.isEmpty() || line.charAt(0) == '#') {
                    continue;
                }
                String[] parts = line.split("\t", -1); // keep the empty target column
                if (parts.length < 3) {
                    continue;
                }
                String registry = parts[0];
                String oldKey = bare(parts[1]);
                String newKey = bare(parts[2]);
                if (newKey.isEmpty()) {
                    removed++;
                    continue;
                }
                registryPairs.computeIfAbsent(registry, k -> new HashMap<>()).put(oldKey, newKey);
                registryPairsInverse.computeIfAbsent(registry, k -> new HashMap<>()).put(newKey, oldKey);
            }
        }
        return removed;
    }

    private static String bare(String key) {
        int colon = key.indexOf(':');
        return colon >= 0 ? key.substring(colon + 1) : key;
    }

    private static String namespace(String key) {
        int colon = key.indexOf(':');
        return colon >= 0 ? key.substring(0, colon) : "";
    }

    // ---- state translation ---------------------------------------------------

    /** 1.21.1 blockstate string -> 26.3 kernel string (pure function). */
    public String layerToKernelState(String state) {
        return translateState(state, true);
    }

    /** 26.3 kernel blockstate string -> 1.21.1 layer string (pure function). */
    public String kernelToLayerState(String state) {
        return translateState(state, false);
    }

    private String translateState(String state, boolean forward) {
        if (state == null || state.isEmpty()) {
            return state;
        }
        int bracket = state.indexOf('[');
        String key = bracket >= 0 ? state.substring(0, bracket) : state;
        String propsPart = bracket >= 0 ? state.substring(bracket + 1, state.length() - 1) : null;
        if (!MINECRAFT.equals(namespace(key) + ":") || !key.startsWith(MINECRAFT)) {
            return state; // modded or malformed: never touch
        }
        String b = bare(key);
        BlockDrift drift;
        String newBare;
        if (forward) {
            drift = blocks.get(b);
            if (drift == null) {
                // pure rename (chain -> iron_chain) lives in the registry table
                String renamed = registryPair("block", b);
                if (renamed == null) {
                    return state;
                }
                return renameOnly(renamed, propsPart);
            }
            newBare = drift.renamedTo != null ? drift.renamedTo : b;
        } else {
            String oldBare = blockRenameInverse.getOrDefault(b, b);
            drift = blocks.get(oldBare);
            if (drift == null) {
                String renamed = registryPairInverse("block", b);
                if (renamed == null) {
                    return state;
                }
                return renameOnly(renamed, propsPart);
            }
            newBare = oldBare;
        }
        Map<String, String> props = parseProps(propsPart);
        if (props == null) {
            return MINECRAFT + newBare;
        }
        Map<String, String> out = new LinkedHashMap<>();
        for (Map.Entry<String, String> e : props.entrySet()) {
            String prop = e.getKey();
            String value = e.getValue();
            PropDrift pd = drift.props.get(prop);
            if (pd == null) {
                out.put(prop, value);
                continue;
            }
            if (forward) {
                if ("removed".equals(pd.kind)) {
                    continue; // prop gone in 26.3
                }
                if ("changed".equals(pd.kind)) {
                    String nv = pd.map.get(value);
                    out.put(prop, nv == null || nv.isEmpty() ? pd.newDefault : nv);
                    continue;
                }
                out.put(prop, value); // "added" cannot occur on old-side input
            } else {
                if ("added".equals(pd.kind)) {
                    continue; // prop did not exist in 1.21.1
                }
                if ("changed".equals(pd.kind)) {
                    String ov = invertGet(pd.map, value);
                    out.put(prop, ov == null ? pd.oldDefault : ov);
                    continue;
                }
                out.put(prop, value); // "removed" cannot occur on new-side input
            }
        }
        return formatState(MINECRAFT + newBare, out);
    }

    private static String renameOnly(String newBare, String propsPart) {
        Map<String, String> props = parseProps(propsPart);
        return props == null ? MINECRAFT + newBare : formatState(MINECRAFT + newBare, props);
    }

    private String registryPair(String registry, String bareOld) {
        Map<String, String> t = registryPairs.get(registry);
        return t == null ? null : t.get(bareOld);
    }

    private String registryPairInverse(String registry, String bareNew) {
        Map<String, String> t = registryPairsInverse.get(registry);
        return t == null ? null : t.get(bareNew);
    }

    private static String invertGet(Map<String, String> map, String value) {
        for (Map.Entry<String, String> e : map.entrySet()) {
            if (e.getValue().equals(value) && !e.getValue().isEmpty()) {
                return e.getKey();
            }
        }
        return null;
    }

    private static Map<String, String> parseProps(String propsPart) {
        if (propsPart == null || propsPart.isEmpty()) {
            return null;
        }
        Map<String, String> props = new LinkedHashMap<>();
        for (String pair : propsPart.split(",")) {
            int eq = pair.indexOf('=');
            if (eq > 0) {
                props.put(pair.substring(0, eq), pair.substring(eq + 1));
            }
        }
        return props;
    }

    private static String formatState(String key, Map<String, String> props) {
        if (props.isEmpty()) {
            return key;
        }
        StringBuilder sb = new StringBuilder(key).append('[');
        boolean first = true;
        for (Map.Entry<String, String> e : props.entrySet()) {
            if (!first) {
                sb.append(',');
            }
            sb.append(e.getKey()).append('=').append(e.getValue());
            first = false;
        }
        return sb.append(']').toString();
    }

    // ---- registry key translation ---------------------------------------------

    /** Registry key 1.21.1 -> 26.3 ("minecraft:boat" -> "minecraft:oak_boat"). */
    public String layerToKernelKey(String registry, String fullKey) {
        return translateKey(registryPairs.get(registry), fullKey, false);
    }

    /** Registry key 26.3 -> 1.21.1 ("minecraft:max_health" -> "minecraft:generic.max_health"). */
    public String kernelToLayerKey(String registry, String fullKey) {
        return translateKey(registryPairsInverse.get(registry), fullKey, true);
    }

    private static String translateKey(Map<String, String> table, String fullKey, boolean inverseTable) {
        if (table == null || fullKey == null || !fullKey.startsWith(MINECRAFT)) {
            return fullKey;
        }
        String mapped = table.get(bare(fullKey));
        if (mapped == null) {
            return fullKey;
        }
        return MINECRAFT + mapped;
    }

    // ---- diagnostics ------------------------------------------------------------

    /** Blocks with any drift (incl. renames). */
    public int blockDriftCount() {
        return blocks.size();
    }

    /** Total paired registry keys across all registries. */
    public int registryPairCount() {
        return registryPairs.values().stream().mapToInt(Map::size).sum();
    }

    /** Registry keys with no 26.3 counterpart (no mapping possible). */
    public int removedKeyCount() {
        return removedKeyCount;
    }

    // ---- selftest -----------------------------------------------------------------

    /** Fixture selftest: {@code java dev.cim.bridge.StateMapper --selftest} (exit 0 = pass). */
    public static void main(String[] args) {
        if (args.length == 0 || !"--selftest".equals(args[0])) {
            System.out.println("usage: StateMapper --selftest");
            return;
        }
        StateMapper m = get();
        int fails = 0;
        fails += check("note identity", m.layerToKernelState("minecraft:note_block[instrument=harp]"),
                "minecraft:note_block[instrument=harp]");
        fails += check("note trumpet reverse", m.kernelToLayerState("minecraft:note_block[instrument=trumpet_oxidized]"),
                "minecraft:note_block[instrument=harp]");
        fails += check("chain rename fwd", m.layerToKernelState("minecraft:chain[axis=y,waterlogged=true]"),
                "minecraft:iron_chain[axis=y,waterlogged=true]");
        fails += check("chain rename rev", m.kernelToLayerState("minecraft:iron_chain[axis=x]"),
                "minecraft:chain[axis=x]");
        fails += check("boat default", m.layerToKernelKey("entity_type", "minecraft:boat"),
                "minecraft:oak_boat");
        fails += check("chest_boat default", m.layerToKernelKey("entity_type", "minecraft:chest_boat"),
                "minecraft:oak_chest_boat");
        fails += check("potion entity", m.layerToKernelKey("entity_type", "minecraft:potion"),
                "minecraft:splash_potion");
        fails += check("attribute flatten", m.layerToKernelKey("attribute", "minecraft:generic.max_health"),
                "minecraft:max_health");
        fails += check("attribute player", m.layerToKernelKey("attribute", "minecraft:player.block_break_speed"),
                "minecraft:block_break_speed");
        fails += check("attribute reverse", m.kernelToLayerKey("attribute", "minecraft:sweeping_damage_ratio"),
                "minecraft:player.sweeping_damage_ratio");
        fails += check("vanilla untouched", m.layerToKernelState("minecraft:stone"), "minecraft:stone");
        fails += check("unknown note value", m.layerToKernelState("minecraft:note_block[instrument=zombie]"),
                "minecraft:note_block[instrument=zombie]");
        fails += check("modded untouched", m.layerToKernelState("cimtest:test_block[foo=bar]"),
                "cimtest:test_block[foo=bar]");
        fails += check("modded key untouched", m.layerToKernelKey("entity_type", "cimtest:test_entity"),
                "cimtest:test_entity");
        fails += check("no-props rename", m.layerToKernelState("minecraft:chain"), "minecraft:iron_chain");
        System.out.println("[c-imagine] StateMapper selftest: blocks=" + m.blockDriftCount()
                + " registryPairs=" + m.registryPairCount()
                + " removedKeys=" + m.removedKeyCount()
                + " -> " + (fails == 0 ? "ALL OK" : fails + " FAILURES"));
        if (fails > 0) {
            System.exit(1);
        }
    }

    private static int check(String what, String actual, String expected) {
        if (!expected.equals(actual)) {
            System.out.println("[c-imagine] StateMapper FAIL " + what + ": got '" + actual
                    + "' expected '" + expected + "'");
            return 1;
        }
        return 0;
    }
}
